def fillomino(n, diag):
    board = [[0] * n for _ in range(n)]
    for i in range(n):
        board[i][i] = diag[i]

    def dfs(x, y, target, visited):
        if x < 0 or x >= n or y < 0 or y >= n or board[x][y] != 0 or (x, y) in visited:
            return False
        visited.add((x, y))
        if board[x][y] != target:
            return False
        board[x][y] = target
        dfs(x + 1, y, target, visited)
        dfs(x - 1, y, target, visited)
        dfs(x, y + 1, target, visited)
        dfs(x, y - 1, target, visited)
        return True

    for i in range(n):
        for j in range(n):
            if board[i][j] == 0:
                visited = set()
                dfs(i, j, diag[i], visited)

    for i in range(n):
